const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length);
const n = Number(tok[0]), q = Number(tok[1]);
const a = [];
for (let i = 0; i < n; i++) a.push(Number(tok[2 + i]));
const mx = new Array(4 * n).fill(0), lz = new Array(4 * n).fill(0);
function build(o, l, r) {
  if (l === r) { mx[o] = a[l]; return; }
  const m = (l + r) >> 1;
  build(2 * o, l, m); build(2 * o + 1, m + 1, r);
  mx[o] = Math.max(mx[2 * o], mx[2 * o + 1]);
}
function apply(o, d) { mx[o] += d; lz[o] += d; }
function push(o) {
  if (lz[o] !== 0) { apply(2 * o, lz[o]); apply(2 * o + 1, lz[o]); lz[o] = 0; }
}
function update(o, l, r, ql, qr, d) {
  if (ql <= l && r <= qr) { apply(o, d); return; }
  push(o);
  const m = (l + r) >> 1;
  if (ql <= m) update(2 * o, l, m, ql, qr, d);
  if (qr > m) update(2 * o + 1, m + 1, r, ql, qr, d);
  mx[o] = Math.max(mx[2 * o], mx[2 * o + 1]);
}
function query(o, l, r, ql, qr) {
  if (ql <= l && r <= qr) return mx[o];
  push(o);
  const m = (l + r) >> 1;
  let best = -Infinity;
  if (ql <= m) best = Math.max(best, query(2 * o, l, m, ql, qr));
  if (qr > m) best = Math.max(best, query(2 * o + 1, m + 1, r, ql, qr));
  return best;
}
build(1, 0, n - 1);
let pos = 2 + n;
const out = [];
for (let i = 0; i < q; i++) {
  if (tok[pos] === "1") {
    update(1, 0, n - 1, Number(tok[pos + 1]) - 1, Number(tok[pos + 2]) - 1, Number(tok[pos + 3]));
    pos += 4;
  } else {
    out.push(query(1, 0, n - 1, Number(tok[pos + 1]) - 1, Number(tok[pos + 2]) - 1));
    pos += 3;
  }
}
console.log(out.join("\n"));

