import java.io.*;
import java.util.*;

public class Main {
    static long[] mx, lz, a;

    static void build(int o, int l, int r) {
        if (l == r) { mx[o] = a[l]; return; }
        int m = (l + r) / 2;
        build(2 * o, l, m);
        build(2 * o + 1, m + 1, r);
        mx[o] = Math.max(mx[2 * o], mx[2 * o + 1]);
    }

    static void apply(int o, long d) { mx[o] += d; lz[o] += d; }

    static void push(int o) {
        if (lz[o] != 0) {
            apply(2 * o, lz[o]);
            apply(2 * o + 1, lz[o]);
            lz[o] = 0;
        }
    }

    static void update(int o, int l, int r, int ql, int qr, long d) {
        if (ql <= l && r <= qr) { apply(o, d); return; }
        push(o);
        int m = (l + r) / 2;
        if (ql <= m) update(2 * o, l, m, ql, qr, d);
        if (qr > m) update(2 * o + 1, m + 1, r, ql, qr, d);
        mx[o] = Math.max(mx[2 * o], mx[2 * o + 1]);
    }

    static long query(int o, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return mx[o];
        push(o);
        int m = (l + r) / 2;
        long best = Long.MIN_VALUE;
        if (ql <= m) best = Math.max(best, query(2 * o, l, m, ql, qr));
        if (qr > m) best = Math.max(best, query(2 * o + 1, m + 1, r, ql, qr));
        return best;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        a = new long[n];
        for (int i = 0; i < n; i++) { in.nextToken(); a[i] = (long) in.nval; }
        mx = new long[4 * n];
        lz = new long[4 * n];
        build(1, 0, n - 1);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            int type = (int) in.nval;
            in.nextToken();
            int l = (int) in.nval - 1;
            in.nextToken();
            int r = (int) in.nval - 1;
            if (type == 1) {
                in.nextToken();
                update(1, 0, n - 1, l, r, (long) in.nval);
            } else {
                out.append(query(1, 0, n - 1, l, r)).append('\n');
            }
        }
        System.out.print(out);
    }
}

