#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n, q;
vector<ll> a, mx, lz;
void build(int o, int l, int r) {
    if (l == r) { mx[o] = a[l]; return; }
    int m = (l + r) / 2;
    build(2 * o, l, m);
    build(2 * o + 1, m + 1, r);
    mx[o] = max(mx[2 * o], mx[2 * o + 1]);
}
void apply(int o, ll d) { mx[o] += d; lz[o] += d; }
void push(int o) {
    if (lz[o]) { apply(2 * o, lz[o]); apply(2 * o + 1, lz[o]); lz[o] = 0; }
}
void update(int o, int l, int r, int ql, int qr, ll d) {
    if (ql <= l && r <= qr) { apply(o, d); return; }
    push(o);
    int m = (l + r) / 2;
    if (ql <= m) update(2 * o, l, m, ql, qr, d);
    if (qr > m) update(2 * o + 1, m + 1, r, ql, qr, d);
    mx[o] = max(mx[2 * o], mx[2 * o + 1]);
}
ll query(int o, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return mx[o];
    push(o);
    int m = (l + r) / 2;
    ll best = LLONG_MIN;
    if (ql <= m) best = max(best, query(2 * o, l, m, ql, qr));
    if (qr > m) best = max(best, query(2 * o + 1, m + 1, r, ql, qr));
    return best;
}
int main() {
    scanf("%d %d", &n, &q);
    a.resize(n);
    for (auto& x : a) scanf("%lld", &x);
    mx.assign(4 * n, 0);
    lz.assign(4 * n, 0);
    build(1, 0, n - 1);
    while (q--) {
        int type, l, r;
        scanf("%d %d %d", &type, &l, &r);
        l--; r--;
        if (type == 1) {
            ll d;
            scanf("%lld", &d);
            update(1, 0, n - 1, l, r, d);
        } else {
            printf("%lld\n", query(1, 0, n - 1, l, r));
        }
    }
    return 0;
}
